                    <h2 id="endpoints-POSTapi-auth-register-officer">Register a new officer and immediately authenticate them, returning a
Sanctum bearer token alongside the canonical safe profile payload.</h2>

<p>
</p>

<p>The route is officer-specific, so the actor is determined by the route:
exactly one Officer record is created (no User or Manager rows), and the
response always reports the Officer actor type. District assignments are
optional at registration: new officers may start with no districts or an
optional, validated <code>district_ids</code> array synced through the pivot, and
<code>is_active</code> defaults to true via the model.</p>
<p>The response follows the canonical auth contract: token fields plus a
single top-level <code>actor_type</code> live on the wrapper, while <code>profile</code>
carries only the cleaned officer identity fields (id, username, email,
badge_number, districts) defined by {@see AuthProfileResource}.</p>

<span id="example-requests-POSTapi-auth-register-officer">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/auth/register/officer" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"username\": \"b\",
    \"email\": \"zbailey@example.net\",
    \"password\": \"|]|{+-\",
    \"confirm_password\": \"architecto\",
    \"badge_number\": \"ngzmiyvdljnikhwa\",
    \"department_ids\": [
        16
    ],
    \"district_ids\": [
        16
    ],
    \"latitude\": -89,
    \"longitude\": -180
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/auth/register/officer"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "username": "b",
    "email": "zbailey@example.net",
    "password": "|]|{+-",
    "confirm_password": "architecto",
    "badge_number": "ngzmiyvdljnikhwa",
    "department_ids": [
        16
    ],
    "district_ids": [
        16
    ],
    "latitude": -89,
    "longitude": -180
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

