                    <h2 id="endpoints-POSTapi-auth-register-user">Register a new user and immediately authenticate them, returning a
Sanctum bearer token alongside the canonical safe profile payload.</h2>

<p>
</p>

<p>The route is user-specific, so the actor is determined by the route:
exactly one User record is created (no Officer or Manager rows), and
the response always reports the User actor type. System-managed fields
(<code>is_active</code>, <code>flag_count</code>, <code>is_under_review</code>) are left to the model
defaults rather than accepted from the client.</p>
<p>The response follows the canonical auth contract: token fields plus a
single top-level <code>actor_type</code> live on the wrapper, while <code>profile</code>
carries only the cleaned user identity fields (id, username, email)
defined by {@see AuthProfileResource}.</p>

<span id="example-requests-POSTapi-auth-register-user">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/auth/register/user" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"username\": \"b\",
    \"email\": \"zbailey@example.net\",
    \"password\": \"|]|{+-\",
    \"confirm_password\": \"architecto\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/auth/register/user"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "username": "b",
    "email": "zbailey@example.net",
    "password": "|]|{+-",
    "confirm_password": "architecto"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

