                    <h2 id="endpoints-PATCHapi-auth-me-districts">Sync the authenticated actor&#039;s own district assignments and return the
refreshed canonical auth profile payload.</h2>

<p>
</p>

<p>Authorization is enforced by {@see UpdateOwnDistrictsRequest}, which
restricts this action to an authenticated, active manager or officer.
Users (who have no district relationship) and any unsupported actor are
rejected with a 403 before this method runs. The actor's <code>districts()</code>
relation is replaced wholesale with the validated, de-duplicated set, and
the response reuses the same {@see AuthProfileResource} shape as
<code>GET /api/auth/me</code>, with <code>actor_type</code> on the wrapper.</p>
<p>This endpoint only touches actor-side district pivots; it never modifies
<code>issues.district_id</code> or reassigns issue districts.</p>

<span id="example-requests-PATCHapi-auth-me-districts">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost/api/auth/me/districts" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"district_ids\": [
        16
    ]
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/auth/me/districts"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "district_ids": [
        16
    ]
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

