                    <h2 id="endpoints-PATCHapi-auth-me">Update the authenticated actor&#039;s own identity fields and return the
refreshed canonical auth profile payload.</h2>

<p>
</p>

<p>Authorization is enforced by {@see UpdateProfileRequest}, which restricts
this action to an authenticated user, officer, or manager. Active actors
may change username, email, password, and (for officers) badge_number;
inactive actors may only change username and password for recovery.
Department, district, and privileged fields are rejected with validation
errors. The response reuses the same {@see AuthProfileResource} shape as
<code>GET /api/auth/me</code>, with <code>actor_type</code> on the wrapper.</p>

<span id="example-requests-PATCHapi-auth-me">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost/api/auth/me" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"username\": \"b\",
    \"password\": \"|]|{+-\",
    \"confirm_password\": \"architecto\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/auth/me"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "username": "b",
    "password": "|]|{+-",
    "confirm_password": "architecto"
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

