                    <h2 id="endpoints-GETapi-main-managers">List main managers with pagination.</h2>

<p>
</p>

<p>Authorization is enforced by IndexMainManagerRequest, which restricts
this action to an authenticated, active, main manager. Results include
only managers with <code>is_main_manager = true</code>, eager-loaded departments
and districts, ordered by username ascending. Pagination is bounded so
<code>per_page</code> can never exceed a safe maximum.</p>

<span id="example-requests-GETapi-main-managers">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/main-managers" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"page\": 16,
    \"per_page\": 22
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/main-managers"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "page": 16,
    "per_page": 22
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

