                    <h2 id="endpoints-PATCHapi-main-managers--manager_id--disable">Disable a main manager without removing the row.</h2>

<p>
</p>

<p>Authorization is enforced by DisableMainManagerRequest. Setting
<code>is_active = false</code> preserves the manager record and historical
associations. Deactivation is blocked when the target is the last active
main manager so the system always retains at least one.</p>

