                    <h2 id="endpoints-PATCHapi-main-managers--manager_id--hub">Set a main manager&#039;s hub and clear their district assignments.</h2>

<p>
</p>

<p>Authorization is enforced by {@see UpdateManagerHubRequest}. Route binding
limits <code>{manager}</code> to rows with <code>is_main_manager = true</code>. Changing the hub
clears the district_manager pivot so assignments can be re-established
within the new hub.</p>

