                    <h2 id="endpoints-GETapi-managers--id-">Show a single ordinary manager profile.</h2>

<p>
</p>

<p>Authorization is enforced by ShowManagerRequest, which restricts this
action to an authenticated, active officer or manager. Route binding
limits the target to rows with <code>is_main_manager = false</code>. Hub scoping
returns 404 when the actor cannot view the manager in the same hub,
including for main managers (no city-wide bypass).</p>

