                    <h2 id="endpoints-POSTapi-managers">Create a new manager on behalf of the authenticated main manager.</h2>

<p>
</p>

<p>Authorization is enforced by StoreManagerRequest, which restricts this
action to an authenticated, active, main manager. The created manager is
an ordinary active manager (never a main manager) linked back to the
creator through <code>created_by_manager_id</code>. No Sanctum token is issued for
the new manager: they must authenticate separately via the shared login
endpoint. The response excludes the password hash, remember token, and
any access tokens.</p>

<span id="example-requests-POSTapi-managers">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/managers" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"username\": \"b\",
    \"email\": \"zbailey@example.net\",
    \"password\": \"|]|{+-\",
    \"confirm_password\": \"architecto\",
    \"department_ids\": [
        16
    ],
    \"district_ids\": [
        16
    ]
}"
</code></pre></div>


<div class="javascript-example">
