                    <h2 id="endpoints-PATCHapi-managers--manager_id--hub">Set an ordinary manager&#039;s hub and clear their district assignments.</h2>

<p>
</p>

<p>Authorization is enforced by {@see UpdateManagerHubRequest}. Changing the
hub invalidates existing district pivots, which are cleared wholesale so
district assignments can be re-established within the new hub.</p>

