                    <h2 id="endpoints-GETapi-officer-sessions">List officer login sessions with pagination.</h2>

<p>
</p>

<p>Authorization is enforced by {@see IndexOfficerSessionRequest}, which
restricts this action to an authenticated, active manager. Optional
<code>officer_id</code>, <code>hub_id</code>, and <code>is_hub_active</code> filters narrow the result set.
Results are ordered newest-first by <code>shift_start</code> then <code>id</code>.</p>

<span id="example-requests-GETapi-officer-sessions">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/officer-sessions" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"officer_id\": 16,
    \"hub_id\": 16,
    \"is_hub_active\": \"0\",
    \"page\": 22,
    \"per_page\": 7
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
