                    <h2 id="endpoints-GETapi-officers">List officers with pagination.</h2>

<p>
</p>

<p>Authorization is enforced by IndexOfficerRequest, which restricts this
action to an authenticated, active officer or manager. Results are
hub-scoped for officers and ordinary managers (same hub only; null hub
yields no rows); main managers see all officers city-wide. Results
exclude soft-deleted officers and default to active officers only when
<code>is_active</code> is omitted. Optional <code>district_id</code> and <code>department_id</code>
filters narrow the hub-scoped result set through the officer's district
and department pivots. Results include eager-loaded departments and
districts, ordered by username ascending. Pagination is bounded so
<code>per_page</code> can never exceed a safe maximum.</p>

<span id="example-requests-GETapi-officers">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/officers" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"district_id\": 16,
    \"department_id\": 16,
    \"is_active\": \"1\",
    \"page\": 22,
    \"per_page\": 7
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/officers"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "district_id": 16,
    "department_id": 16,
    "is_active": "1",
    "page": 22,
    "per_page": 7
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

