                    <h2 id="endpoints-PATCHapi-officers--officer_id--districts">Sync a target officer&#039;s district assignments on behalf of an active
manager and return the officer&#039;s refreshed profile payload.</h2>

<p>
</p>

<p>Authorization is enforced by {@see UpdateOfficerDistrictsRequest} (active
manager only; wrong actor type 403). Hub scoping via
ManagerOfficerHubAccess returns 404 when the ordinary manager cannot
administer the target officer. The officer is
resolved through route model binding, their <code>districts()</code> relation is
replaced wholesale with the validated, de-duplicated set, and the
response reuses the canonical {@see AuthProfileResource} officer shape.</p>
<p>This endpoint only touches the officer-side district pivot; it never
modifies <code>issues.district_id</code> or reassigns issue districts.</p>

