                    <h2 id="endpoints-GETapi-categories">List categories ordered by priority (main) then name (subcategory).</h2>

<p>
</p>

<p>Departments and parent are eager loaded to avoid N+1 queries, and main
categories carry their nested children. Main categories sort by ascending
<code>priority</code> (lower number = higher priority), then <code>name</code>; null priority
sorts last. Subcategories sort by <code>name</code> ascending.</p>

<span id="example-requests-GETapi-categories">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/categories" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


