                    <h2 id="endpoints-POSTapi-categories">Create a category and attach its departments.</h2>

<p>
</p>

<p>Authorization and hierarchy/priority validation are enforced by
StoreCategoryRequest. The category and its pivot assignments are written
in a single transaction so a failed attach never leaves an orphan row.</p>

<span id="example-requests-POSTapi-categories">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/categories" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"name\": \"b\",
    \"parent_id\": 16,
    \"department_ids\": [
        16
    ],
    \"priority\": 22,
    \"is_active\": true
}"
</code></pre></div>


