                    <h2 id="endpoints-PUTapi-categories--id-">Update a category and, when provided, re-sync its departments.</h2>

<p>
</p>

<p>Only the validated keys present in the request are applied, so partial
updates leave untouched fields intact. Departments are only re-synced
when <code>department_ids</code> is included in the payload.</p>

<span id="example-requests-PUTapi-categories--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost/api/categories/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"name\": \"b\",
    \"parent_id\": 16,
    \"department_ids\": [
        16
    ],
    \"priority\": 22,
    \"is_active\": false
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/categories/1"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "name": "b",
    "parent_id": 16,
    "department_ids": [
        16
    ],
    "priority": 22,
    "is_active": false
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

