                    <h2 id="endpoints-DELETEapi-categories--id-">Hard delete an eligible category.</h2>

<p>
</p>

<p>A main category that still has subcategories is rejected with a 409 so
the hierarchy is never orphaned. The pivot rows are removed by the
database cascade, but any <code>issues.category_id</code> reference uses
<code>restrictOnDelete</code>; that constraint failure is caught and returned as a
409 conflict rather than surfacing as a 500.</p>

<span id="example-requests-DELETEapi-categories--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request DELETE \
    "http://localhost/api/categories/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/categories/1"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};


fetch(url, {
    method: "DELETE",
    headers,
}).then(response =&gt; response.json());</code></pre></div>

