                    <h2 id="endpoints-DELETEapi-departments--id-">Hard delete a department.</h2>

<p>
</p>

<p>Authorization (active main manager only) is enforced by the route's
UpdateDepartmentRequest-equivalent gate through the dedicated
authorization helper below. Deletion is rejected when the department is
still assigned to any manager or officer through the <code>department_manager</code>
or <code>department_officer</code> pivots, because managers and officers must each
have one or more departments: removing the row would orphan those actors
and break the at-least-one-department invariant. Once no actor references
the department, deleting it relies on the <code>category_department</code> pivot's
<code>cascadeOnDelete</code> foreign keys to remove the category assignments
automatically; the category rows themselves are never touched, so
historical issue context is preserved.</p>

<span id="example-requests-DELETEapi-departments--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request DELETE \
    "http://localhost/api/departments/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"code\": \"b\",
    \"name\": \"n\",
    \"is_active\": true
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/departments/1"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "code": "b",
    "name": "n",
    "is_active": true
};

fetch(url, {
    method: "DELETE",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

