                    <h2 id="endpoints-POSTapi-districts">Create a district.</h2>

<p>
</p>

<p>Authorization (active main manager only) and validation are enforced by
StoreDistrictRequest. Only validated district attributes are persisted;
actor district assignments remain managed through their dedicated pivot
endpoints.</p>

<span id="example-requests-POSTapi-districts">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/districts" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"hub_id\": 16,
    \"name\": \"n\",
    \"postal_prefix\": \"gzmiyv\",
    \"center_lat\": -89,
    \"center_lng\": -179,
    \"radius_meters\": 4,
    \"is_active\": true
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/districts"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "hub_id": 16,
    "name": "n",
    "postal_prefix": "gzmiyv",
    "center_lat": -89,
    "center_lng": -179,
    "radius_meters": 4,
    "is_active": true
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

