                    <h2 id="endpoints-PUTapi-districts--id-">Update a district.</h2>

<p>
</p>

<p>Authorization (active main manager only) and validation are enforced by
UpdateDistrictRequest. Only provided validated keys are applied, so partial
updates leave untouched fields intact.</p>

<span id="example-requests-PUTapi-districts--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost/api/districts/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"hub_id\": 16,
    \"name\": \"n\",
    \"postal_prefix\": \"gzmiyv\",
    \"center_lat\": -89,
    \"center_lng\": -179,
    \"radius_meters\": 4,
    \"is_active\": false
}"
</code></pre></div>


