                    <h2 id="endpoints-DELETEapi-districts--id-">Hard delete an eligible district.</h2>

<p>
</p>

<p>Authorization (active main manager only) is enforced by
DeleteDistrictRequest. Deletion is rejected when the district is still assigned to any manager,
assigned to any officer, or referenced by any issue. This keeps actor
assignments intact and preserves the singular <code>issues.district_id</code> issue
location/reference boundary.</p>

<span id="example-requests-DELETEapi-districts--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request DELETE \
    "http://localhost/api/districts/1" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


