                    <h2 id="endpoints-GETapi-issues">List issues with composable filters, visibility scoping, and pagination.</h2>

<p>
</p>

<p>Results are visibility-scoped per actor type before optional filters:
users see visible canonicals, their own issues (any visibility), or
canonicals they participate on; officers and ordinary managers see issues
in assigned districts (including hidden); main managers see all issues
city-wide. Duplicate child rows are excluded by default per actor
(<code>IssueListScope</code>); users may use <code>participating=1</code> for owned children
with canonical participation, and officers/managers may use
<code>include_duplicates=1</code> to include children. A single Eloquent query
applies the optional <code>district_id</code>, <code>department</code>, <code>category_id</code>, <code>status</code>,
<code>assigned_officer_id</code>, <code>unassigned</code>, <code>mine</code>, <code>participating</code>,
<code>include_duplicates</code>, and <code>visibility</code> filters conditionally and
cumulatively (AND with visibility), so any subset (or all) of the
filters may be combined to narrow the result set.
The <code>department</code> filter is resolved through the issue departments
relationship with any-match semantics. Results are eager loaded (including
<code>officer_resolution</code> with officer and attachments when a report exists;
<code>status_history</code> is omitted on list), ordered newest-first by <code>created_at</code>
then <code>id</code>, and paginated with a safe default <code>per_page</code>.</p>

<span id="example-requests-GETapi-issues">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/issues" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"district_id\": 16,
    \"department\": \"architecto\",
    \"category_id\": 16,
    \"status\": \"opgelost\",
    \"assigned_officer_id\": 16,
    \"unassigned\": \"1\",
    \"mine\": \"1\",
    \"participating\": \"1\",
    \"include_duplicates\": \"1\",
    \"visibility\": \"visible\",
    \"page\": 22,
    \"per_page\": 7
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
