                    <h2 id="endpoints-POSTapi-issues">Create an issue on behalf of the authenticated regular user.</h2>

<p>
</p>

<p>Authorization (active user only) and validation are enforced by
StoreIssueRequest. Normal creates delegate to {@see CreateIssue} (creator
participant, <code>participant_count = 1</code>). When <code>duplicate_of_id</code> is present,
{@see CreateIssueAsDuplicate} creates a hidden child linked to the
canonical target and returns the child resource. The issue remains
user-owned through <code>user_id</code> even when reported anonymously. Departments
and <code>priority</code> are derived server-side from the selected category.
Anonymous reports receive a stable server-generated <code>anonymous_alias</code>.</p>

<span id="example-requests-POSTapi-issues">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/issues" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"title\": \"b\",
    \"content\": \"architecto\",
    \"category_id\": 16,
    \"district_id\": 16,
    \"postal_code\": \"ngzmiy\",
    \"address\": \"v\",
    \"latitude\": -89,
    \"longitude\": -179,
    \"is_anonymous\": false,
    \"duplicate_of_id\": 16
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/issues"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "title": "b",
    "content": "architecto",
    "category_id": 16,
    "district_id": 16,
    "postal_code": "ngzmiy",
    "address": "v",
    "latitude": -89,
    "longitude": -179,
    "is_anonymous": false,
    "duplicate_of_id": 16
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

</span>

