                    <h2 id="endpoints-GETapi-issues--issue_id--duplicates">List duplicate children for a canonical issue.</h2>

<p>
</p>

<p>Authorization is enforced by IndexIssueDuplicatesRequest, which restricts
this action to an authenticated, active officer or manager. The target
must be a canonical issue; duplicate child route ids return 422
issue_not_canonical. Issues not visible to the actor return 404.
Children are ordered oldest-first by created_at then id and paginated
with full IssueResource payloads (officers and managers are never
participant-redacted).</p>

<span id="example-requests-GETapi-issues--issue_id--duplicates">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/issues/16/duplicates" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"page\": 16,
    \"per_page\": 22
}"
</code></pre></div>


