                    <h2 id="endpoints-POSTapi-issues--issue_id--mark-duplicate">Link an existing issue to a canonical duplicate target.</h2>

<p>
</p>

<p>Officers must be assigned to both the child and canonical districts
(403 officer_not_in_district). Managers rely on IssueVisibilityQuery
only. Different owners re-parent the child as a hidden duplicate; same
owner merges participants onto the canonical and hard-deletes the child.
Tier C: hub-active session required for officers.</p>

