                    <h2 id="endpoints-GETapi-issues--id-">Show a single issue with its eager-loaded relations.</h2>

<p>
</p>

<p>Visibility is enforced after route binding: users may view visible issues,
their own issues (any visibility), or canonical issues they participate on
(with canonical content redacted at the resource layer); officers and
ordinary managers may view issues in assigned districts; main managers
may view any issue city-wide. Unauthorized or invisible issues return 404
to avoid leaking existence. Embeds <code>officer_resolution</code> when a report
exists. Active officers and managers also receive <code>status_history</code> (newest
first); regular users do not.</p>

<span id="example-requests-GETapi-issues--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/issues/16" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


