                    <h2 id="endpoints-PUTapi-issues--id-">Update an owner&#039;s issue, applying only the validated, owner-editable
fields.</h2>

<p>
</p>

<p>Ownership and authorization are enforced by UpdateIssueRequest. Only the
keys present in the validated payload are applied, so partial updates
leave untouched fields intact. When <code>category_id</code> is supplied the issue's
departments and integer <code>priority</code> are re-derived from the new category
and re-synced through the pivot source of truth (supporting multiple
departments per issue); departments and priority are never accepted from
the client. The <code>user_id</code> is never reassigned and the server-generated <code>anonymous_alias</code> is never accepted
from the client: toggling <code>is_anonymous</code> on lazily generates a stable
alias only when one does not already exist (so an existing alias is
preserved), while toggling it off clears the alias.</p>

<span id="example-requests-PUTapi-issues--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost/api/issues/16" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"title\": \"b\",
    \"content\": \"architecto\",
    \"category_id\": 16,
    \"district_id\": 16,
    \"postal_code\": \"ngzmiy\",
    \"address\": \"v\",
    \"latitude\": -89,
    \"longitude\": -179,
    \"is_anonymous\": true
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/issues/16"
);

const headers = {
    "Content-Type": "application/json",
