};

let body = {
    "title": "b",
    "content": "architecto",
    "category_id": 16,
    "district_id": 16,
    "postal_code": "ngzmiy",
    "address": "v",
    "latitude": -89,
    "longitude": -179,
    "is_anonymous": true
};

fetch(url, {
    method: "PUT",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

