                    <h2 id="endpoints-PATCHapi-issues--issue_id--visibility">Set an issue&#039;s visibility to visible or hidden.</h2>

<p>
</p>

<p>Authorization is enforced by UpdateIssueVisibilityRequest (active officer or
manager only). Visibility scope is enforced after route binding via
IssueVisibilityQuery::canViewIssue(), matching show behavior: issues the
actor cannot view return 404. Only the visibility field is updated.</p>

<span id="example-requests-PATCHapi-issues--issue_id--visibility">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost/api/issues/16/visibility" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"visibility\": \"hidden\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/issues/16/visibility"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "visibility": "hidden"
};

fetch(url, {
    method: "PATCH",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

