                    <h2 id="endpoints-POSTapi-issues--issue_id--assign-self">Self-assign the authenticated officer to an issue in their district.</h2>

<p>
</p>

<p>Resolved (opgelost) and closed (gesloten) issues cannot be self-assigned (422
issue_not_assignable). Open issues also transition to in_behandeling with one
status history row. Already assigned to the requesting officer is idempotent.
Assignment to a different officer returns 409 without takeover.</p>

