                    <h2 id="endpoints-PATCHapi-issues--issue_id--status">Update an assigned issue&#039;s status along the directed officer workflow.</h2>

<p>
</p>

<p>District access is checked before locking. Assignee ownership and
transition validation run on the locked row. Visibility scope returns
404 when the issue is not viewable. Each successful change appends one
status history row without coordinates and may set resolved_at on the
first transition to opgelost.</p>

<span id="example-requests-PATCHapi-issues--issue_id--status">
