                    <h2 id="endpoints-GETapi-issues--issue_id--officer-resolution-attachments--attachment_id--download">Stream a resolution attachment file back to an authorized actor.</h2>

<p>
</p>

<p>Download authorization is enforced by DownloadOfficerIssueResolutionAttachmentRequest
via IssueVisibilityQuery (Q8 / D15-A visibility-only): users who may view the issue,
and any active officer or manager. Hidden issues follow existing visibility rules
(404 when not viewable). The attachment must belong to the issue's resolution —
a mismatch yields 404 so attachment ids cannot be probed across issues — and the
backing file must still exist on the non-public <code>local</code> disk.</p>

