                    <h2 id="endpoints-DELETEapi-issues--id-">Hard delete an owner&#039;s issue.</h2>

<p>
</p>

<p>Owner-only: officers and managers cannot delete issues they do not own
(enforced by {@see DeleteIssueRequest}). Duplicate children delegate to
{@see DeleteDuplicateChild} with optional <code>leave_participation</code> in the
request body (default false — keep canonical participation). Canonical
issues delegate to {@see ReparentOnCanonicalDelete}, which promotes the
oldest child when duplicates exist. This is a hard delete, not a soft
delete: rows are removed outright and attachment FK cascades apply.</p>

<span id="example-requests-DELETEapi-issues--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request DELETE \
    "http://localhost/api/issues/16" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"leave_participation\": true
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/issues/16"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "leave_participation": true
};

fetch(url, {
    method: "DELETE",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

