                    <h2 id="endpoints-POSTapi-issues--issue_id--attachments">Store one or more uploaded files against an owner&#039;s issue.</h2>

<p>
</p>

<p>Ownership, the per-file size/MIME constraints, the per-request file count,
and the cumulative cap against already-stored attachments are all enforced
by StoreIssueAttachmentRequest. Each validated file is written to the
non-public <code>local</code> disk under a per-issue directory using a hashed storage
name, and one IssueAttachment row is persisted per file capturing the
storage path, original filename, MIME type, byte size, and upload time.
The newly created attachments are returned as a <code>data</code>-wrapped collection
whose URLs point at the authenticated download endpoint, never a public
storage URL. The wrapping is applied explicitly here because the resource
itself disables wrapping (<code>$wrap = null</code>) for the flat single-resource
shape used elsewhere, while this upload endpoint contractually returns
<code>{ "data": [ ... ] }</code>.</p>

<span id="example-requests-POSTapi-issues--issue_id--attachments">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/issues/16/attachments" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "files[]=@C:\Users\marti\AppData\Local\Temp\php3.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/issues/16/attachments"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('files[]', document.querySelector('input[name="files[]"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

