                    <h2 id="endpoints-DELETEapi-issues--issue_id--attachments--id-">Delete a single attachment from an owner&#039;s issue.</h2>

<p>
</p>

<p>Owner-only authorization is enforced by DeleteIssueAttachmentRequest, which
restricts the action to the authenticated, active regular user who owns the
route issue. The attachment must belong to the issue named in the route — a
mismatch yields a 404 so attachment ids cannot be probed or removed across
issues. The backing file is removed from the non-public <code>local</code> disk (a
missing file is tolerated so a partial prior cleanup cannot block deletion)
and the attachment row is deleted, returning an empty 204 response.</p>

<span id="example-requests-DELETEapi-issues--issue_id--attachments--id-">
<blockquote>Example request:</blockquote>


<div class="bash-example">
